<script setup>
const props=defineProps({config:Object,compact:Boolean});const emit=defineEmits(['patch','commit']);
function update(key,value){emit('patch',{[key]:value});}
const fonts=[['sans-serif','系统无衬线'],['PingFang SC','苹方'],['Microsoft YaHei','微软雅黑'],['monospace','等宽字体'],['serif','衬线字体']];
const typography=[['fontSize','标题字号',16,80,1,'px'],['letterSpacing','标题字距',0,24,.5,'px'],['titleX','标题 X',0,1600,1,'px'],['titleY','标题 Y',0,600,1,'px'],['subtitleSize','副标题字号',6,24,1,'px'],['subtitleSpacing','副标题字距',0,12,.5,'px'],['subtitleOffset','副标题间距',12,100,1,'px'],['subtitleOpacity','副标题透明度',0,1,.05,''],['textGlow','文字辉光',0,20,.5,'px']];
function number(e,key,min,max){const n=Number(e.target.value);if(Number.isFinite(n))update(key,Math.max(min,Math.min(max,n)));}
</script>
<template><div class="header-appearance" :class="{'ha-compact':compact}">
 <label class="ha-text">主标题<input :value="config.title" aria-label="主标题" maxlength="160" @input="update('title',$event.target.value)" @change="emit('commit')"/></label>
 <label class="ha-text">副标题<input :value="config.subtitle" aria-label="副标题" maxlength="160" @input="update('subtitle',$event.target.value)" @change="emit('commit')"/></label>
 <div class="ha-colors"><label v-for="[key,label] in [['titleColor','标题颜色'],['accent','副标题颜色']]" :key="key">{{label}}<span><input type="color" :value="config[key]" :aria-label="label" @input="update(key,$event.target.value)" @change="emit('commit')"/><input :value="config[key]" :aria-label="label+' HEX'" maxlength="7" @change="/^#[0-9a-f]{6}$/i.test($event.target.value)&&(update(key,$event.target.value),emit('commit'))"/></span></label></div>
 <details :open="!compact"><summary>文字排版与光效 <span>TYPOGRAPHY</span></summary>
 <label class="ha-row">字体<select :value="config.fontFamily" aria-label="Header 字体" @change="update('fontFamily',$event.target.value);emit('commit')"><option v-for="[id,name] in fonts" :key="id" :value="id">{{name}}</option></select></label>
 <label class="ha-row">字重<select :value="config.fontWeight" aria-label="Header 字重" @change="update('fontWeight',Number($event.target.value));emit('commit')"><option v-for="w in [300,400,500,600,700]" :key="w" :value="w">{{w}}</option></select></label>
 <label v-for="[key,label,min,max,step,unit] in typography" :key="key" class="ha-row">{{label}}<span class="ha-number"><input type="number" :value="config[key]" :aria-label="label" :min="min" :max="max" :step="step" @input="number($event,key,min,max)" @change="emit('commit')"/><small>{{unit}}</small></span></label>
 <label class="ha-row ha-toggle">渐变标题<input type="checkbox" :checked="config.titleGradient" aria-label="渐变标题" @change="update('titleGradient',$event.target.checked);emit('commit')"/></label>
 <label v-if="config.titleGradient" class="ha-row">渐变终点<input type="color" :value="config.titleGradientTo" aria-label="标题渐变终点" @input="update('titleGradientTo',$event.target.value)" @change="emit('commit')"/></label>
 </details>
 <details><summary>背景与适配 <span>COMPOSITION</span></summary>
 <label class="ha-row">背景可见度<span class="ha-range"><input type="range" :value="config.background.opacity" min="0" max="1" step=".05" aria-label="背景可见度" @input="emit('patch',{background:{...config.background,opacity:Number($event.target.value)}})" @change="emit('commit')"/><small>{{Math.round(config.background.opacity*100)}}%</small></span></label>
 <label class="ha-row">画布底色<input type="color" :value="config.bgColor" aria-label="画布底色" @input="update('bgColor',$event.target.value)" @change="emit('commit')"/></label>
 <label class="ha-row">底色透明度<span class="ha-number"><input type="number" :value="config.bgOpacity" min="0" max="1" step=".05" aria-label="底色透明度" @input="number($event,'bgOpacity',0,1)" @change="emit('commit')"/></span></label>
 <label class="ha-row">组件适配<select :value="config.fit" aria-label="Header 适配方式" @change="update('fit',$event.target.value);emit('commit')"><option value="stretch">填满组件</option><option value="contain">等比完整显示</option><option value="cover">等比铺满裁切</option></select></label>
 </details>
</div></template>
<style scoped>
.header-appearance{font-family:inherit;font-size:11px;color:#62796f}.ha-text{display:flex;flex-direction:column;gap:8px;margin:15px 0}.ha-text>input{min-width:0;width:100%;height:34px;padding:0 9px;background:#f8faf9;border:1px solid #e1e8e4;border-radius:5px;color:#334c43;font-size:11px;outline:none}.header-appearance input:focus,.header-appearance select:focus{outline:2px solid #54a38b44;outline-offset:1px}.ha-colors{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin:17px 0}.ha-colors>label{display:flex;flex-direction:column;gap:8px;font-size:10px}.ha-colors>label>span{display:flex;align-items:center;gap:5px;border:1px solid #e0e9e4;border-radius:4px;padding:5px}.header-appearance input[type=color]{height:22px;width:25px;border:0;padding:0;background:none;cursor:pointer}.ha-colors input:not([type=color]){width:65px;min-width:0;border:0;background:none;font:10px monospace;color:#70867b;outline:none}.header-appearance details{border-top:1px solid #e6ece8;padding:14px 0 2px}.header-appearance summary{font-size:11px;font-weight:550;cursor:pointer;color:#4d685c;display:flex;align-items:center;gap:7px;list-style:none}.header-appearance summary:before{content:'›';transition:transform .15s}.header-appearance details[open]>summary:before{transform:rotate(90deg)}.header-appearance summary>span{margin-left:auto;color:#a4b6ac;font:6px monospace;letter-spacing:.6px}.ha-row{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:13px 0;font-size:10px}.ha-row>select,.ha-number{height:29px;width:127px;border:1px solid #e0e9e4;border-radius:4px;background:#fbfdfc;color:#506c5f;font-size:10px}.ha-number{display:flex;align-items:center;padding:0 7px;gap:3px}.ha-number input{width:100%;min-width:0;outline:none;border:0;background:none;color:inherit;font:11px monospace}.ha-number small{font-size:9px;color:#a0b0a6}.ha-range{display:flex;align-items:center;width:127px;gap:8px}.ha-range input{width:90px;accent-color:#348b72}.ha-range small{font:9px monospace;color:#80988b}.ha-toggle input{accent-color:#348b72;height:15px;width:15px}.ha-compact{font-size:10px}.ha-compact summary>span{font-size:6px}
</style>
